// Every JS object has an internal [[Prototype]] link to another object.
// Property lookups walk up this chain until found, or until they reach
// null. This delegation is what "inheritance" really is in JS -- there
// are no real classes under the hood; class syntax is sugar over this.
const animal = {
  speak() { return this.name + ' makes a sound.'; },
};

const dog = Object.create(animal); // dog's prototype is animal
dog.name = 'Rex';
dog.speak = function () { return this.name + ' barks.'; }; // own property shadows animal.speak

const cat = Object.create(animal);
cat.name = 'Tom'; // no own speak -- lookup walks up to animal.speak

Swal.fire(
  dog.speak() + ' | ' + cat.speak() +
  ' | dog prototype === animal: ' + (Object.getPrototypeOf(dog) === animal) +
  ' | animal prototype === Object.prototype: ' + (Object.getPrototypeOf(animal) === Object.prototype)
);

// The call stack runs synchronous code first, top to bottom, to
// completion. Only once the stack is empty does the event loop pull
// from the microtask queue (Promise callbacks, queueMicrotask) --
// draining it COMPLETELY -- before it pulls a single task from the
// macrotask queue (setTimeout, setInterval, I/O callbacks). This is
// why a Promise.then callback always wins a race against setTimeout(fn, 0).
const log = [];

log.push('1: sync (script start)');

setTimeout(() => {
  log.push('4: setTimeout callback (macrotask)');
  Swal.fire(log.join(' -> '));
}, 0);

Promise.resolve().then(() => {
  log.push('3: promise.then (microtask)');
});

log.push('2: sync (script end)');

// V8 uses a generational, mark-and-sweep-based collector: starting from
// a set of "roots" (the global object, the currently executing call
// stack), it marks every object reachable by following references, then
// sweeps (frees) everything that was NOT marked. An object is only
// eligible for collection once nothing reachable from a root still
// references it -- a "leak" in JS almost always means an unintended
// reference is still being kept alive, not a literal memory bug like in C.
function createLeak() {
  const bigArray = new Array(1e6).fill('leaked-data');
  // Returning a closure that references bigArray keeps the whole array
  // alive for as long as the returned function exists, even though the
  // caller only wanted a small label.
  return function leakyClosure(label) {
    return label + ' (array length still alive: ' + bigArray.length + ')';
  };
}

const closure = createLeak(); // bigArray cannot be collected while closure exists
Swal.fire(closure('demo'));

// Common real leak sources: event listeners added but never removed,
// growing caches/arrays with no eviction, timers holding closures that
// reference large objects and are never cleared, and detached DOM nodes
// still referenced from JS after being removed from the page.

// Debounce delays running a function until AFTER a burst of calls has
// gone quiet for 'delay' ms -- every new call resets the timer. Use it
// for something like a search-as-you-type input, where you only want to
// fire the API call once the user pauses typing, not on every keystroke.
function debounce(fn, delay) {
  let timeoutId;
  return function (...args) {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => fn.apply(this, args), delay);
  };
}

const searchLog = [];
const debouncedSearch = debounce((term) => searchLog.push('searched: ' + term), 300);

debouncedSearch('r');
debouncedSearch('re');
debouncedSearch('rea'); // only this last call survives -- the first two are cancelled

setTimeout(() => {
  Swal.fire('Calls that actually ran: ' + searchLog.length + ' | ' + (searchLog[0] || '(none yet)'));
}, 400);

// Throttle guarantees a function runs at most once per 'interval', no
// matter how many times it's called -- unlike debounce, it does NOT
// wait for calls to stop; it fires on a regular cadence. Use it for
// high-frequency events like scroll or mousemove, where you want a
// steady stream of updates without running on every single event.
function throttle(fn, interval) {
  let lastCall = 0;
  return function (...args) {
    const now = Date.now();
    if (now - lastCall >= interval) {
      lastCall = now;
      return fn.apply(this, args);
    }
  };
}

const calls = [];
const throttledLog = throttle((i) => calls.push(i), 200);

// Simulate 5 rapid, synchronous calls -- only the first passes through
// immediately, because 200ms hasn't elapsed between the rest of them.
for (let i = 1; i <= 5; i++) throttledLog(i);

Swal.fire('Calls that passed through immediately: ' + JSON.stringify(calls) + ' (the rest need 200ms to elapse first)');

// Before ES modules existed, the Module Pattern used an IIFE
// (Immediately Invoked Function Expression) plus closures to fake
// private state: variables declared inside the IIFE are inaccessible
// from the outside, and only the returned object's methods can touch
// them. It's still useful today for encapsulating state on a single
// object without a class, and it's the clearest way to see how
// closures create true privacy in JS -- unlike a plain object literal,
// where every property is public.
const counterModule = (function () {
  let count = 0; // private -- not reachable from outside this IIFE

  return {
    increment() { return ++count; },
    reset() { count = 0; return count; },
  };
})();

counterModule.increment();
counterModule.increment();
Swal.fire('Count via increment(): ' + counterModule.increment() + ' | direct access to count: ' + counterModule.count);

// A Singleton guarantees a class/module has exactly ONE instance shared
// everywhere it's used -- common for things like a single database
// connection pool, a config object, or a logger, where creating a
// second instance would be wasteful or incorrect.
class Configuration {
  static #instance; // private static field holds the one instance

  constructor() {
    if (Configuration.#instance) {
      return Configuration.#instance; // return the existing instance instead of a new one
    }
    this.settings = { env: 'production' };
    Configuration.#instance = this;
  }
}

const configA = new Configuration();
configA.settings.env = 'staging'; // mutate through one reference
const configB = new Configuration(); // "new" but returns the SAME instance

Swal.fire('Same instance: ' + (configA === configB) + ' | configB sees the change: ' + configB.settings.env);

// A Factory is a function that creates and returns objects without
// exposing the construction details (which class, which branch of
// logic) to the caller -- handy when object creation involves
// branching that you don't want scattered across every call site.
function createUser(role) {
  const base = { role, createdAt: Date.now() };
  switch (role) {
    case 'admin':
      return { ...base, permissions: ['read', 'write', 'delete'] };
    case 'editor':
      return { ...base, permissions: ['read', 'write'] };
    default:
      return { ...base, permissions: ['read'] };
  }
}

const admin = createUser('admin');
const guest = createUser('guest');

Swal.fire('admin permissions: ' + admin.permissions.join(', ') + ' | guest permissions: ' + guest.permissions.join(', '));

// Observer lets one object (the "subject") maintain a list of
// dependents ("observers") and notify all of them automatically when
// its state changes -- this is the foundation under pub/sub systems,
// DOM events, and reactive state libraries. It decouples the subject
// from its observers: the subject doesn't need to know what they
// actually do with the notification.
class Subject {
  #observers = [];

  subscribe(fn) {
    this.#observers.push(fn);
    return () => { this.#observers = this.#observers.filter(o => o !== fn); }; // unsubscribe
  }

  notify(data) {
    this.#observers.forEach(fn => fn(data));
  }
}

const priceFeed = new Subject();
const results = [];
const unsubscribe = priceFeed.subscribe((price) => results.push('Observer A saw: ' + price));
priceFeed.subscribe((price) => results.push('Observer B saw: ' + price));

priceFeed.notify(100);
unsubscribe(); // Observer A stops listening
priceFeed.notify(200);

Swal.fire(results.join(' | '));

// Currying transforms a function that takes multiple arguments into a
// sequence of functions that each take one (or a few) -- useful for
// building specialized functions from a general one by fixing some
// arguments early (partial application). Composition combines several
// single-purpose functions into a pipeline, instead of nesting calls
// like c(b(a(x))) by hand.
const curry = (fn) => (...args) =>
  args.length >= fn.length ? fn(...args) : (...more) => curry(fn)(...args, ...more);

const add3 = (a, b, c) => a + b + c;
const curriedAdd3 = curry(add3);
const addToTen = curriedAdd3(10); // partially applied -- 'a' is fixed at 10

const compose = (...fns) => (input) => fns.reduceRight((acc, fn) => fn(acc), input);
const double = (n) => n * 2;
const increment = (n) => n + 1;
const doubleThenIncrement = compose(increment, double); // increment(double(x))

Swal.fire(
  'curried add(10)(5)(1) = ' + curriedAdd3(10)(5)(1) +
  ' | addToTen(5, 1) = ' + addToTen(5, 1) +
  ' | compose: doubleThenIncrement(3) = ' + doubleThenIncrement(3)
);

// A shallow clone (spread, Object.assign, Array.prototype.slice) only
// copies the top level -- nested objects/arrays are still SHARED by
// reference with the original, so mutating a nested value through the
// clone also mutates the original. A deep clone copies every level
// recursively so the clone is fully independent.
const original = { name: 'demo', address: { city: 'Delhi' } };

const shallow = { ...original };
shallow.address.city = 'Mumbai'; // mutates the SAME nested object as original

// JSON.parse(JSON.stringify(x)) is a common deep-clone trick, but it
// silently drops functions, undefined, and Symbols, turns Dates into
// strings, and throws on circular references.
const original2 = { name: 'demo', address: { city: 'Delhi' } };
const jsonClone = JSON.parse(JSON.stringify(original2));
jsonClone.address.city = 'Chennai'; // fully independent copy

// structuredClone (built into modern browsers and Node 17+) is the
// correct general-purpose deep clone: it handles Dates, Maps, Sets,
// ArrayBuffers, and circular references properly, but still cannot
// clone functions or DOM nodes.
const structClone = structuredClone(original2);

Swal.fire(
  'original.address.city after shallow-clone mutation: ' + original.address.city +
  ' | original2.address.city after jsonClone mutation (unaffected): ' + original2.address.city +
  ' | structClone.address is a real independent object: ' + (structClone.address !== original2.address)
);

// Event delegation exploits event bubbling: instead of attaching a
// listener to every individual child element (expensive for long or
// dynamically-changing lists, and it misses elements added later),
// attach ONE listener to a shared ancestor and inspect event.target to
// figure out which child was actually interacted with. This scales to
// any number of children, including ones added after the listener was set up.
const list = document.createElement('ul');
['Apples', 'Bananas', 'Cherries'].forEach((item) => {
  const li = document.createElement('li');
  li.textContent = item;
  list.appendChild(li);
});

// ONE listener on the parent handles clicks on any current or future <li>
list.addEventListener('click', (event) => {
  if (event.target.tagName === 'LI') {
    Swal.fire('You clicked: ' + event.target.textContent);
  }
});

// Added AFTER the listener was attached -- still works, no extra listener needed
const laterItem = document.createElement('li');
laterItem.textContent = 'Dates (added after the listener)';
list.appendChild(laterItem);
list.style.cssText = 'position:fixed;bottom:12px;right:12px;background:#fff;border:1px solid #ccc;padding:8px 12px;z-index:9999;';
document.body.appendChild(list);

Swal.fire('A small list was appended to the bottom-right of the page with a single delegated click listener on its <ul>. Click any item in it to see event.target identify exactly which one was clicked.');

// All four take an array of promises but differ in HOW they settle:
// - Promise.all: resolves once ALL succeed (with an array of values),
//   but rejects immediately as soon as ANY one rejects (fail-fast).
// - Promise.allSettled: always resolves once every promise is done,
//   with a status ('fulfilled'/'rejected') per promise -- it never
//   short-circuits, so you get a full picture even with failures.
// - Promise.race: settles as soon as the FIRST promise settles,
//   whether it fulfills or rejects.
// - Promise.any: resolves as soon as the FIRST promise FULFILLS,
//   ignoring rejections, and only rejects if EVERY promise rejects.
const ok = (value, ms) => new Promise((resolve) => setTimeout(() => resolve(value), ms));
const fail = (reason, ms) => new Promise((_, reject) => setTimeout(() => reject(reason), ms));

async function demo() {
  const allResult = await Promise.all([ok('A', 10), fail('B failed', 5)])
    .catch(err => 'all() rejected fail-fast: ' + err);

  const settled = await Promise.allSettled([ok('A', 50), fail('B failed', 30), ok('C', 70)]);

  const winner = await Promise.race([ok('slow', 100), fail('fast failure', 20)])
    .catch(err => 'race rejected: ' + err);

  const firstSuccess = await Promise.any([fail('x', 10), ok('first real success', 40)]);

  Swal.fire(
    'all(): ' + allResult +
    ' | allSettled statuses: ' + JSON.stringify(settled.map(r => r.status)) +
    ' | race (settles on whichever finishes first, even a rejection): ' + winner +
    ' | any (ignores rejections, resolves on first success): ' + firstSuccess
  );
}

demo();

// An iterator is any object with a .next() method that returns
// { value, done }. A generator (function*) is a convenient way to
// build one: calling it doesn't run the function body immediately --
// it returns an iterator, and the body only runs up to the next
// 'yield' each time .next() is called, pausing with its local state
// intact in between. This makes it easy to represent lazy or infinite
// sequences without computing them all up front.
function* idGenerator() {
  let id = 1;
  while (true) { // infinite, but safe -- only produces a value when asked
    yield id++;
  }
}

const ids = idGenerator();
const firstThree = [ids.next().value, ids.next().value, ids.next().value];

// Generators are also iterable, so they work with for-of and spread --
// here wrapping the infinite generator to safely take a finite slice.
function* take(iterator, count) {
  for (let i = 0; i < count; i++) {
    const { value, done } = iterator.next();
    if (done) return;
    yield value;
  }
}

const nextFive = [...take(ids, 5)];

Swal.fire('First 3 ids: ' + firstThree.join(', ') + ' | next 5 ids (generator remembers where it left off): ' + nextFive.join(', '));

// A regular Map/Set holds a STRONG reference to its keys/values, which
// keeps them alive in memory for as long as the Map/Set itself exists
// -- even if nothing else in the app references that object anymore.
// WeakMap holds a WEAK reference to its keys (WeakSet to its values):
// if an object has no other references left, the garbage collector is
// free to reclaim it, and its entry silently disappears from the
// WeakMap/WeakSet too. This makes them ideal for attaching metadata to
// objects you don't own the lifecycle of -- e.g. caching data per DOM
// node -- without preventing that object from ever being collected
// once it's removed from the page.
const metadata = new WeakMap();

let el = { tagName: 'DIV' }; // stands in for a DOM node in this demo
metadata.set(el, { clickCount: 0, createdAt: Date.now() });
metadata.get(el).clickCount++;

Swal.fire('Metadata while el is referenced: ' + JSON.stringify(metadata.get(el)));

el = null; // no other references remain -- the engine is now free to
           // collect the original object, and its WeakMap entry goes
           // with it automatically. Unlike a regular Map, we never had
           // to remember to call metadata.delete(el) ourselves.

// WeakMap/WeakSet deliberately have no size, no keys(), and no for-of
// support -- their contents can vanish at any GC pause, so exposing an
// enumerable API would be misleading. This is the trade-off for the
// memory-safety guarantee.
Swal.fire('WeakMap has no size/iteration API by design: ' + (typeof metadata.size === 'undefined' && typeof metadata.keys === 'undefined'));
